  tapped_at  TEXT NOT NULL,                -- YYYY-MM-DD HH:MM
  stop_id    INTEGER NOT NULL REFERENCES stops(stop_id),
  kind       TEXT NOT NULL CHECK (kind IN ('in', 'out'))
);
